// Entirely self-authored fixture generated by scripts/ios/make_native_scene_fixture.py.
// This proves native GPU readback on a detached layer, not physical iPad presentation.
#include <gtest/gtest.h>

#include "support/gpu_scene.hpp"
#include "support/pixels.hpp"

#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <string>

TEST(IOSSceneStartupRender, PackedQuadShaderAndTextureRenderWithoutSharedAssets)
{
    const char* root = std::getenv("WM_NATIVE_SCENE_FIXTURE");
    if (root == nullptr || root[0] == '\0') {
        GTEST_SKIP() << "set WM_NATIVE_SCENE_FIXTURE to the generated packed project directory";
    }
    WE_SKIP_WITHOUT_METAL();

    // Keep this package alive until after GpuScene releases its VFS and renderer.
    // Copy no loose scene/shaders: the real parser must read the virtual package entry.
    // GpuScene supplies an empty shared-assets folder and a null sound backend.
    we_test::ScenePackage package;
    for (const char* name : { "project.json", "scene.pkg", "preview.png" }) {
        std::ifstream input(std::filesystem::path(root) / name, std::ios::binary);
        ASSERT_TRUE(input) << "missing fixture file: " << name;
        const std::string bytes((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
        ASSERT_FALSE(bytes.empty()) << name;
        package.Put(name, bytes);
    }
    ASSERT_FALSE(package.Contains("scene.json"));
    ASSERT_FALSE(package.Contains("shaders/qa_quad.vert"));
    ASSERT_FALSE(package.Contains("materials/qa_quadrants.tex"));

    we_test::GpuScene scene(package);
    ASSERT_TRUE(scene.ok()) << scene.error();
    // Observe the first real encoded frame, not a library preview or a synthetic fallback.
    ASSERT_TRUE(scene.Step()) << scene.error();
    const we_test::Image frame = scene.Picture();
    ASSERT_EQ(frame.width, 256u);
    ASSERT_EQ(frame.height, 144u);
    EXPECT_TRUE(we_test::ExpectPixel(frame, 32, 18, { 255, 0, 0, 255 }, 2));
    EXPECT_TRUE(we_test::ExpectPixel(frame, 224, 18, { 0, 255, 0, 255 }, 2));
    EXPECT_TRUE(we_test::ExpectPixel(frame, 32, 126, { 0, 0, 255, 255 }, 2));
    EXPECT_TRUE(we_test::ExpectPixel(frame, 224, 126, { 255, 255, 0, 255 }, 2));
    EXPECT_EQ(scene.frames(), 1u);
    EXPECT_EQ(scene.FirstFramePasses().scene_output_passes, 1u);
}
